SUBSCRIPTIONS = [
    {'name': 'sub-prod', 'policy_assigned': True, 'diagnostics_enabled': True, 'public_ips': 0},
    {'name': 'sub-dev', 'policy_assigned': True, 'diagnostics_enabled': False, 'public_ips': 2},
]

def score(sub):
    checks = [
        ('policy_assigned', sub.get('policy_assigned') is True),
        ('diagnostics_enabled', sub.get('diagnostics_enabled') is True),
        ('no_public_ip', sub.get('public_ips') == 0),
    ]
    failed = [name for name, ok in checks if not ok]
    return len(checks) - len(failed), failed

for sub in SUBSCRIPTIONS:
    passed, failed = score(sub)
    if failed:
        print(f"{sub['name']}: {passed}/3 FAIL ({', '.join(failed)})")
    else:
        print(f"{sub['name']}: {passed}/3 PASS")
